          {turn.idx > 0 && <button type="button" className="btn btn--ghost qcard__wrap" onClick={onWrap} disabled={locked} aria-busy={busy === 'wrap'}>여기까지로 정리하기</button>}
        </footer>
      </form>
    </section>
